    pub async fn serve_with_listener_shutdown<F>(
        self,
        listener: StdTcpListener,
        signal: F,
    ) -> Result<()>
    where
        F: Future<Output = ()>,
    {
        self.inner
            .serve_with_listener_shutdown(listener, signal)
            .await
    }
}

